package com.ruoyi.medical.persistence;
import javax.sql.DataSource;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.*;
/** Explicit DocumentReview lane. Production dependencies must be installed; no provider fallback. */
@Configuration(proxyBeanMethods=false)
@ConditionalOnProperty(name="medical.professional-runtime.document-review-enabled",havingValue="true",matchIfMissing=false)
public class DocumentReviewInvocationConfiguration {
 @Bean DocumentReviewInvocationProduction documentReviewInvocationProduction(DocumentReviewExecutionService jobs,DataSource data){return new DocumentReviewInvocationProduction(jobs,data);}
 @Bean(name="documentReviewInvocationHttpSchema") TaskInvocationHttpSchema documentReviewInvocationHttpSchema(FormalInvocationSchema schema)throws Exception{return new TaskInvocationHttpSchema(schema);}
 @Bean DocumentReviewInvocationSchema taskDocumentReviewInvocationSchema()throws Exception{return new DocumentReviewInvocationSchema();}
 @Bean DocumentReviewInvocationObjects taskDocumentReviewInvocationObjects(DataSource data,PermissionSchema json,FormalInvocationSchema schema,DocumentReviewInvocationSchema exact,DependencyManifestSchema manifests){return new DocumentReviewInvocationObjects(data,json,schema,exact,manifests);}
 @Bean DocumentReviewInvocationRecords taskDocumentReviewInvocationRecords(DataSource data,DocumentReviewInvocationObjects objects,FormalInvocationSchema schema,PermissionSchema json,DocumentReviewInvocationProduction producers){return new DocumentReviewInvocationRecords(data,objects,schema,json,producers);}
 @Bean DocumentReviewInvocationContext taskDocumentReviewInvocationContext(DataSource data,ModelConfigurationService models,ModelEligibilityAuthority eligibility,ResourceReadAuthority resources,SourceReadAuthority sources,TaskInvocationPackages packages,FormalInvocationSourceOriginals originals,FormalInvocationSchema schema,DocumentReviewInvocationSchema exact,PermissionSchema json,@Qualifier("formalInvocationObjectTransport")RuntimeObjectTransport transport,DocumentReviewInvocationProduction producers,DocumentReviewContextReads contentReads){return new DocumentReviewInvocationContext(data,models,eligibility,resources,sources,packages,originals,schema,exact,json,transport,producers,contentReads);}
 @Bean DocumentReviewInvocationService taskDocumentReviewInvocationService(DataSource data,DocumentReviewSupervisor supervisors,DocumentReviewWorkerAccess workers,RunTokenAuthority tokens,DocumentReviewInvocationContext contexts,DocumentReviewInvocationRecords records,FormalInvocationReservations reservations,FormalInvocationDispatch dispatch,FormalInvocationReceiptObjects receipts,FormalInvocationSettlement settlement,FormalInvocationObjectRegistration objects,FormalProviderCaptureEvidence captures,FormalInvocationSchema schema)throws Exception{return new DocumentReviewInvocationService(data,supervisors,workers,tokens,contexts,records,reservations,dispatch,receipts,settlement,objects,new TaskInvocationResults(data,null,settlement,objects,captures,schema),schema);}
 @Bean DocumentReviewInvocationContextOrchestrator taskDocumentReviewInvocationContextOrchestrator(DocumentReviewHostAccess hosts,DocumentReviewSupervisor supervisors,DocumentReviewInvocationContext contexts,FormalInvocationSourceOriginals originals,TaskInvocationPackages packages,FormalTokenizerRunner tokenizer,DocumentReviewInvocationObjects objects,@Qualifier("formalInvocationObjectTransport")RuntimeObjectTransport transport,DocumentReviewInvocationRecords records,DocumentReviewInvocationService invocations){return new DocumentReviewInvocationContextOrchestrator(hosts,supervisors,contexts,originals,packages,tokenizer,objects,transport,records,invocations);}
 @Bean(name="documentReviewInvocationLocalBridge") TaskInvocationLocalBridge documentReviewInvocationLocalBridge(org.springframework.core.env.Environment e){String p="medical.professional-runtime.document-review-gateway.";return new TaskInvocationLocalBridge(new TaskInvocationLocalBridge.Configuration(java.nio.file.Path.of(e.getRequiredProperty(p+"executable")),e.getRequiredProperty(p+"executable-sha256"),java.nio.file.Path.of(e.getRequiredProperty(p+"entrypoint")),e.getRequiredProperty(p+"entrypoint-sha256"),java.nio.file.Path.of(e.getRequiredProperty(p+"package-root")),java.nio.file.Path.of(e.getRequiredProperty(p+"package-manifest")),e.getRequiredProperty(p+"package-manifest-sha256"),java.nio.file.Path.of(e.getRequiredProperty(p+"private-configuration")),java.time.Duration.ofSeconds(Long.parseLong(e.getRequiredProperty(p+"timeout-seconds")))));}
 @Bean DocumentReviewInvocationBridge taskDocumentReviewInvocationBridge(DocumentReviewInvocationContextOrchestrator contexts,DocumentReviewInvocationService service,@Qualifier("documentReviewInvocationLocalBridge")TaskInvocationLocalBridge bridge,org.springframework.core.env.Environment e)throws Exception{return new DocumentReviewInvocationBridge(contexts,service,bridge,java.time.Duration.ofSeconds(Long.parseLong(e.getRequiredProperty("medical.professional-runtime.document-review-model-token-lifetime-seconds"))));}
}
